"""Build an evidence report: actual webpage comparisons separated from offline asset studies."""
import json
import hashlib
from pathlib import Path
import shutil
from PIL import Image

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/quality-report'
before=json.loads((OUT/'baseline.json').read_text(encoding='utf-8'))
after=json.loads((OUT/'rebuild.json').read_text(encoding='utf-8'))
assert before['result']==after['result']=='passed'
assert after['htmlSha256']==hashlib.sha256((ROOT/'docs/index.html').read_bytes()).hexdigest(),'Recapture the current application before building the report'
merge_before=json.loads((OUT/'merge-before.json').read_text(encoding='utf-8'))
assert merge_before['result']=='passed'
for report in [before,after,merge_before]:
    for case in report['cases']:
        for shot in case['shots']:
            raw=ROOT/shot['sourceFile'] if shot.get('sourceFile') else OUT/shot['file']
            source=raw if raw.exists() else OUT/shot['file']
            if source.suffix=='.png':
                image=Image.open(source).convert('RGB');image.thumbnail((1600,1800),Image.Resampling.LANCZOS)
                image.save(OUT/source.with_suffix('.webp').name,'WEBP',quality=94,method=6)
                shot['file']=source.with_suffix('.webp').name
    (OUT/(report['stage']+'.json')).write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
for name in ['sofa','chair','master-bed','kitchen-east']:
    source=ROOT/f'work/rebuild/studio-{name}.png'
    if source.exists():
        image=Image.open(source).convert('RGB');image.save(OUT/f'studio-{name}.webp','WEBP',quality=94,method=6)
    else:
        assert (OUT/f'studio-{name}.webp').exists(),'Unchanged source assets need their preserved studio evidence'
seams=json.loads((ROOT/'validation/rebuild-seams-visual.json').read_text(encoding='utf-8'))
topology=json.loads((ROOT/'validation/rebuild-topology.json').read_text(encoding='utf-8'))
assert seams['result']==topology['result']=='passed'
assert topology['authoringScriptSha256']==json.loads((ROOT/'assets/rebuild/models.json').read_text())['authoringScriptSha256']
assert all(c['htmlSha256']==after['htmlSha256'] and c['authoringScriptSha256']==topology['authoringScriptSha256'] for c in seams['cases'] if c['stage']=='after'),'Recapture current asset close-ups'
(OUT/'seams').mkdir(exist_ok=True)
for case in seams['cases']:
    for shot in case['shots']:
        source=ROOT/'work/seams/inspection'/shot['file']
        target=OUT/'seams'/source.with_suffix('.webp').name
        Image.open(source).convert('RGB').save(target,'WEBP',quality=96,method=6)
        shot['file']='seams/'+target.name
for filename in ['merge-balcony-validation.json','rebuild-topology.json','rebuild-seams-visual.json','rebuild-assets.json','rebuild-decor.json','rebuild-mobile-compatibility.json','rebuild-render-quality.json','rollback-v15-render-quality.json']:
    data=json.loads((ROOT/'validation'/filename).read_text(encoding='utf-8'))
    assert data.get('result')=='passed' or filename=='rebuild-decor.json' and data['viewports'] and not data['errors']
    if filename=='rebuild-seams-visual.json':
        (OUT/filename).write_text(json.dumps(seams,indent=2)+'\n',encoding='utf-8')
    else:
        shutil.copyfile(ROOT/'validation'/filename,OUT/filename)
budgets=json.loads((ROOT/'assets/rebuild/model-report.json').read_text())
balcony=json.loads((ROOT/'validation/merge-balcony-validation.json').read_text(encoding='utf-8'))
assert balcony['result']=='passed'
for image in (ROOT/'validation').glob('merge-balcony-*.webp'):
    shutil.copyfile(image,OUT/image.name)
summary={'before':before,'mergeBefore':merge_before,'after':after,'models':budgets,'seams':seams,'topology':topology['totals'],'htmlMB':(ROOT/'docs/index.html').stat().st_size/1e6,'qualityAcceptance':'pending-user-visual-review-and-real-phone'}
embedded=json.dumps(summary,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>家装 A · 材质与模型重建报告</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f3ee;color:#2c3931;font:15px/1.75 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1180px;margin:auto;padding:46px 28px 70px}a{color:#2c6952}h1{font-size:clamp(28px,4vw,44px);line-height:1.25;letter-spacing:-1px;margin:12px 0 18px}h2{font-size:23px;margin-top:36px}p{max-width:900px}.eyebrow{font-size:12px;letter-spacing:2px;color:#667461}.tag{border:1px solid #cbd1c4;border-radius:30px;padding:4px 12px;font-size:12px;display:inline-block}.links{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}.links a{padding:9px 15px;border:1px solid #c8d1c1;border-radius:6px;text-decoration:none;background:white}.links a:first-child{background:#2e6650;color:white}.notice{background:#e9eadf;border-left:3px solid #8a916e;padding:14px 18px;border-radius:4px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:25px 0}.stat{background:white;padding:18px;border:1px solid #dddcd0;border-radius:9px}.stat b{display:block;font-size:27px;color:#2c6952}.small{font-size:12px;color:#69736a}.tabs{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}button{font:inherit;background:white;border:1px solid #cdd4c6;color:#354c3c;border-radius:5px;padding:8px 14px;cursor:pointer}button[aria-pressed=true]{background:#2e6650;color:white;border-color:#2e6650}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #bf8d3a;outline-offset:3px}.compare{position:relative;border-radius:8px;overflow:hidden;background:#232d26;--split:50%}.compare img{display:block;width:100%;height:auto}.compare .before{position:absolute;inset:0;clip-path:inset(0 calc(100% - var(--split)) 0 0)}.compare .before img{height:100%;object-fit:fill}.compare:after{content:"";position:absolute;left:var(--split);top:0;bottom:0;width:2px;background:#ffffff9c;pointer-events:none}.compare.mobile{max-width:390px;margin:auto}.labels{position:absolute;top:12px;left:12px;right:12px;display:flex;justify-content:space-between;pointer-events:none}.labels span{background:#1a2b21db;color:white;font-size:12px;border-radius:4px;padding:4px 10px}.slider{display:flex;align-items:center;gap:16px;margin:13px 0}.slider input{flex:1;accent-color:#2e6650;min-width:60px}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0;background:#fff;border:1px solid #d9ded2;border-radius:8px;overflow:hidden}figure img{width:100%;display:block}figcaption{padding:12px 16px;font-size:13px}.scroll{overflow:auto;border:1px solid #d7dcca;border-radius:7px}table{border-collapse:collapse;width:100%;background:white;font-size:13px}td,th{padding:10px 15px;text-align:left;border-bottom:1px solid #e1e5da;white-space:nowrap}th{background:#e9eddf}tr:last-child td{border-bottom:0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}ul{padding-left:22px}code{background:#e6e9df;padding:2px 5px;border-radius:3px;overflow-wrap:anywhere}footer{border-top:1px solid #d7ddce;margin-top:30px;padding-top:20px;font-size:12px;color:#667064}@media(max-width:650px){main{padding:28px 17px 45px}.stats,.columns,.gallery{grid-template-columns:1fr}.stat{padding:12px 16px}.links a,button{font-size:13px}.columns{gap:0}}
</style></head><body><main><div class="eyebrow">杭州 · 璞荟铭庭 / ASSET RECONSTRUCTION</div><h1>家装 A · 材质与模型重建</h1><span class="tag">main · V16.2 合并效果验证</span><p>画质重建与接缝修复已合入 main，后续在主干开发。本版将 V16.1 家装 A 资产与主干阳台顶板、顶灯及配套烘焙组合，按桌面、手机视口与微信 UA 重新验证。</p><nav class="links"><a href="../?decor=a">打开 main 测试页</a><a href="../?verify=mobile">本机微信 / 浏览器检测</a><a href="#seams">本轮接缝修复</a><a href="../deployment.json">部署提交</a></nav><div class="notice"><strong>当前状态：</strong>完成 16 类主要家具资产的重建和网页接入，建立可编辑源文件、米制 UV、PBR 资源、离线局部遮蔽和 PC / 手机 LOD。<strong>工业级整体效果尚未最终验收</strong>：全屋照明使用主干已完成的阳台顶板 / 顶灯烘焙，实际手机微信、持续热稳定性和用户目视评审待完成。</div><div class="stats"><div class="stat">资产重建<b>16 类 · 双 LOD</b><span class="small">沙发、桌椅、柜体、床、灯具与厨卫主要家具</span></div><div class="stat">材质来源<b>CC0 PBR · 13 张驻留图</b><span class="small">1024px PC / 512px 手机；颜色、法线、粗糙度分别处理</span></div><div class="stat">清晰度策略<b>恢复原画布规格</b><span class="small">保留原画布规格、WebGL1 与手机兼容阴影</span></div></div><section id="integration"><h2>主干合并 · 阳台与灯光保留验证</h2><p>主模板冲突按功能组合处理：保留主干完整阳台屋顶、顶灯、屋顶贴图坐标、天花板设置与烘焙快照；接入画质分支家具、PBR 和接缝修复。建筑 / 门洞及家具位置保持。下方为合并后的真实网页画布，桌面和手机竖 / 横屏均重新采集。</p><div class="gallery"><figure><img src="merge-balcony-desktop-a-night.webp" alt="主干合并后桌面阳台夜晚"><figcaption>PC · 家装 A 阳台夜晚，顶灯开关 / 调光通过</figcaption></figure><figure><img src="merge-balcony-desktop-ceiling-light.webp" alt="主干合并后阳台顶面和顶灯"><figcaption>PC · 完整顶面与吸顶灯，屋顶覆盖无缺口</figcaption></figure><figure><img src="merge-balcony-wechat-portrait-a-night.webp" alt="手机视口阳台夜晚"><figcaption>手机竖屏 · 微信 UA / mobile LOD，非物理手机</figcaption></figure><figure><img src="merge-balcony-wechat-landscape-day.webp" alt="手机横屏阳台白天"><figcaption>手机横屏 · 关灯自然光，保留阳台遮阳顶板</figcaption></figure></div><p><a href="merge-balcony-validation.json">阳台 / 灯光 / 天花板材质与保存检查</a> · <a href="merge-visual.json">合并前后同机位实际像素检查</a></p></section><section id="seams"><h2>V16.1 · 漏边漏缝修复近检</h2><p>重建旋转件轴心与吊灯内壁，封闭并焊接管件端口；被褥改为与床垫接触的连续厚壳；水槽盆沿覆盖开孔，橱柜侧板与台面完成收口。软包缝线贴合实际曲面，并闭合沙发连续管架。所有材质共用同一位置量化网格，避免材质边界产生微缝。</p><div class="notice">16 类资产的 <strong>__SOLIDS__ 个实体部件 × PC / 手机两档</strong>，逐件检查实际导出三角形：开放边、非流形边、退化面、绕序与法线错误均为 <strong>0</strong>。水槽台面每档 4,386 条覆盖射线无缺口；被褥 / 床垫、柜侧 / 台面接触距离通过。窗帘双面材质已独立，家具维持正面剔除。</div><p class="small">以下是同一网页内嵌模型在固定中性灯光下的 WebGL1 近检。左侧为 V16，右侧为 main V16.2；PC 使用 high，手机使用 mobile 几何与 512px 贴图。它们是模型检查图，与下方实际房间灯光截图分开；未用图片修补几何。</p><div class="tabs" id="seamScenes"></div><div class="compare" id="seamCompare"><img id="seamAfter" alt="接缝修复后 WebGL 模型近检"><div class="before"><img id="seamBefore" alt="接缝修复前 WebGL 模型近检"></div><div class="labels"><span>修复前 · V16</span><span>修复后 · V16.2</span></div></div><label class="slider">修复前<input id="seamSplit" type="range" min="0" max="100" value="50" aria-label="调整接缝修复前后对比">修复后</label><p id="seamCaption" class="small"></p><p class="small">使用下方 PC / 手机切换也会同步此处。<a href="rebuild-topology.json">逐部件拓扑与装配检查</a> · <a href="rebuild-seams-visual.json">机位与近检采集记录</a></p></section><h2>实际网页 · 合并前后同机位对比</h2><p class="small">下方均为网页 WebGL 画布截图。PC 与手机视口各 6 组：客厅昼夜、主卧、毛坯、餐厅和厨房。相机、眼高、FOV 和灯光状态一致；未重绘或补光。默认比较 V16.1 分支与合并后 main，也可切换到最初 V14.2 基线。</p><div class="tabs" id="devices"><button data-device="pc">PC · 1280 × 800</button><button data-device="mobile">手机视口 · 390 × 844</button></div><div class="tabs" id="baselineTabs"><button data-baseline="merge">V16.1 分支 → main</button><button data-baseline="original">V14.2 原版 → main</button></div><div class="tabs" id="scenes"></div><div class="compare" id="compare"><img id="afterImage" alt="重建后网页实际画面"><div class="before"><img id="beforeImage" alt="原 V14.2 网页实际画面"></div><div class="labels"><span id="baselineLabel">分支 · V16.1</span><span>main · V16.2</span></div></div><label class="slider">原版<input id="split" type="range" min="0" max="100" value="50" aria-label="调整重建前后对比">重建</label><p class="small" id="caption"></p><h2>独立模型检查 · 离线 Cycles 棚拍</h2><p class="small">以下使用同一个 Blender 源模型、UV 与 PBR 材质在独立软箱光环境中渲染，用于检查曲面、倒角、缝线和构造。它们<strong>不是网页效果图或手机截图</strong>，不能替代上方实时场景。</p><div class="gallery"><figure><img src="studio-sofa.webp" loading="lazy" alt="沙发独立模型检查"><figcaption>独立软包、弯管镀铬框架、圆角与缝线</figcaption></figure><figure><img src="studio-chair.webp" loading="lazy" alt="曲木餐椅独立模型检查"><figcaption>有厚度的弯曲木背、悬臂钢管和坐垫包边</figcaption></figure><figure><img src="studio-master-bed.webp" loading="lazy" alt="床独立模型检查"><figcaption>床框板件、床垫包边、枕头曲面和有厚度的被褥</figcaption></figure><figure><img src="studio-kitchen-east.webp" loading="lazy" alt="橱柜独立模型检查"><figcaption>板件、门缝、踢脚凹位、柜门把手与台面倒角</figcaption></figure></div><h2>资产预算</h2><div class="scroll"><table><thead><tr><th>资产</th><th>PC 三角形</th><th>手机三角形</th><th>材质组</th></tr></thead><tbody id="budgets"></tbody></table></div><p class="small" id="bytes"></p><h2>本机短时观测</h2><p class="small">Windows + Chrome / RTX 5080 上采样，手机列只是触控 / 微信 UA 视口模拟，受约 30 FPS 限制；PC 受约 60 FPS 限制。数据不能推断真实手机性能提升。启动时间包含本机服务、脚本、纹理和首次构造，单次样本不作速度结论。</p><div class="scroll"><table><thead><tr><th>设备 / 场景</th><th>原版 FPS</th><th>重建 FPS</th><th>画布 前 → 后</th></tr></thead><tbody id="performance"></tbody></table></div><div class="columns"><section><h2>已通过的检查</h2><ul><li>WebGL1 高 / 手机 LOD 的逐部件封闭性、绕序 / 法线、退化面、装配净距和资源加载检查。</li><li>主干含阳台的 219 张建筑烘焙全部加载；13 张 PBR 驻留图，重复数据共享。</li><li>建筑快照相同、屋顶 0 缺口，门闭合 / 扫掠和家具净空通过。</li><li>柜背 / 床头贴墙、床三侧通行、原安全观景位置和设置保存回归。</li><li>Chromium / Windows WebKit、微信 UA、横竖屏及缺 HDR / depth 回退。</li></ul></section><section><h2>工业级目标的剩余验收</h2><ul><li>逐房间按原 A 参考图进行视觉评审，避免只按资产数量判断效果。</li><li>全屋自然光 / 夜间光照仍需进一步标定；完整 Cycles GI 尚未接入网页。</li><li>房门、窗框、储藏架和洗烘沿用已有细化模型，未全部替换为 Blender 新资产。</li><li>真实 iPhone / Android 微信的清晰度、发热、连续 10 分钟性能。</li><li>资源体积增加，需要结合真实网络和手机设备确认加载预算。</li></ul></section></div><h2>源文件与许可</h2><p>原始参考图与结构数据保持。家具源文件为 <code>assets/rebuild/reference-a-master.blend</code>，材质来自 Poly Haven CC0 的木饰面、织物、人字拼地板与石材；仓库保存原始来源和 SHA256。构建检查资产生成脚本哈希，避免修改源文件后误用过期导出资源。主应用保持单 HTML，运行时无 CDN 或外部资产请求。</p><p><a href="https://github.com/aimspike/HangZhouPHMT/tree/main/assets/rebuild">查看资产源文件与预算</a> · <a href="public-validation.json">当前 main 公网验证</a> · <a href="rebuild-assets.json">资产与实际渲染检查</a> · <a href="rebuild-decor.json">家具 / 门 / 保存回归</a> · <a href="rebuild-mobile-compatibility.json">引擎与手机视口检查</a> · <a href="rebuild-render-quality.json">昼夜与扩展回退</a> · <a href="baseline.json">原版采样</a> / <a href="rebuild.json">重建采样</a></p><footer>2026-11-25 · 回退提交 2377c58 · 原版基线 7b53b23。画质功能已合入 main，后续在主干开发；feature 保留历史快照，release 独立发布。此报告不宣称照片级、真实手机验证或工业级最终验收。</footer></main><script>const DATA=__DATA__;
const titles={'living-day':'客厅 · 白天','living-night':'客厅 · 夜晚','master-day':'主卧 · 白天','bare-day':'毛坯 · 白天','dining-day':'餐厅 · 白天','kitchen-day':'厨房 · 白天'},modelNames={'sofa':'沙发','coffee':'茶几','console':'电视柜','dining-table':'圆餐桌','chair':'曲木餐椅','pendant':'多层吊灯','master-bed':'主卧床','second-bed':'次卧床','master-wardrobe':'主卧衣柜','second-wardrobe':'次卧衣柜','sideboard':'餐边柜','fridge':'冰箱','kitchen-east':'东侧橱柜','kitchen-north':'北侧橱柜','study-desk':'书桌','vanity':'浴室柜'};let device=location.hash==='#mobile'?'mobile':'pc',scene='living-day',seamScene='sink',comparison='merge';const $=id=>document.getElementById(id);for(const id of Object.keys(titles)){const button=document.createElement('button');button.textContent=titles[id];button.dataset.scene=id;button.onclick=()=>{scene=id;update()};$('scenes').append(button)}for(const button of $('devices').children)button.onclick=()=>{device=button.dataset.device;history.replaceState(null,'','#'+device);update()};for(const b of $('baselineTabs').children)b.onclick=()=>{comparison=b.dataset.baseline;update()};function update(){const a=(comparison==='merge'?DATA.mergeBefore:DATA.before).cases.find(c=>c.id===device).shots.find(s=>s.id===scene),b=DATA.after.cases.find(c=>c.id===device).shots.find(s=>s.id===scene);$('baselineLabel').textContent=comparison==='merge'?'分支 · V16.1':'原版 · V14.2';for(const b of $('baselineTabs').children)b.setAttribute('aria-pressed',String(b.dataset.baseline===comparison));$('beforeImage').src=a.file;$('afterImage').src=b.file;$('compare').classList.toggle('mobile',device==='mobile');$('caption').textContent=titles[scene]+' · FOV '+b.metrics.fov+'° · 眼高 1.5m · 同机位实际网页画布';for(const x of $('devices').children)x.setAttribute('aria-pressed',String(x.dataset.device===device));for(const x of $('scenes').children)x.setAttribute('aria-pressed',String(x.dataset.scene===scene));updateSeam();}$('split').oninput=e=>$('compare').style.setProperty('--split',e.target.value+'%');let rows='';for(const [id,b] of Object.entries(DATA.models.models))rows+='<tr><td>'+modelNames[id]+'</td><td>'+b.high.triangles.toLocaleString()+'</td><td>'+b.mobile.triangles.toLocaleString()+'</td><td>'+b.high.drawGroups+'</td></tr>';$('budgets').innerHTML=rows;$('bytes').textContent='自包含 HTML 约 '+DATA.htmlMB.toFixed(2)+' MB，包含 PC 与手机两套资产；报告资源不由看房页自动加载。';rows='';for(const a of DATA.before.cases){const b=DATA.after.cases.find(c=>c.id===a.id);for(const x of a.shots){const y=b.shots.find(s=>s.id===x.id);rows+='<tr><td>'+(a.id==='pc'?'PC':'手机视口')+' / '+titles[x.id]+'</td><td>'+x.metrics.observedFps.toFixed(1)+'</td><td>'+y.metrics.observedFps.toFixed(1)+'</td><td>'+x.metrics.diagnostics.canvas.join('×')+' → '+y.metrics.diagnostics.canvas.join('×')+'</td></tr>'}}$('performance').innerHTML=rows;const seamTitles={sofa:'软包 · 缝线贴合与管架',sink:'水槽 · 盆沿与台面',quilt:'被褥 · 连续厚壳与床垫',shade:'吊灯 · 内壁与收口',tube:'钢管 · 封口与连接'};for(const id of Object.keys(seamTitles)){const b=document.createElement('button');b.dataset.seam=id;b.textContent=seamTitles[id];b.onclick=()=>{seamScene=id;updateSeam()};$('seamScenes').append(b)}function updateSeam(){const find=stage=>DATA.seams.cases.find(c=>c.device===device&&c.stage===stage).shots.find(s=>s.id===seamScene);const a=find('before'),b=find('after');$('seamBefore').src=a.file;$('seamAfter').src=b.file;$('seamCompare').classList.toggle('mobile',device==='mobile');$('seamCaption').textContent=seamTitles[seamScene]+' · '+(device==='pc'?'PC high':'手机 mobile')+' · 正面剔除 · 固定中性检查灯光';for(const x of $('seamScenes').children)x.setAttribute('aria-pressed',String(x.dataset.seam===seamScene));}$('seamSplit').oninput=e=>$('seamCompare').style.setProperty('--split',e.target.value+'%');update();</script></body></html>'''
